&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi Genel Başkan Yardımcısı Mustafa Yılmaz, iktidara yakın medya kuruluşlarına verilen reklam s&amp;uuml;relerini a&amp;ccedil;ıkladı. &amp;ldquo;Bu taksimi kurt yapmaz kuzulara şah olsa&amp;rdquo; diyerek iktidarın kendisine yakın medya kuruluşlarına&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;1 yılda tam 19 milyon 712 bin 677 saniye reklam vermesine tepki g&amp;ouml;sterdi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Mustafa Yılmaz, Saadet Partisi Genel Merkezinde ger&amp;ccedil;ekleştirdiği basın a&amp;ccedil;ıklamasında, &amp;ldquo;İktidara destek veren medya organları reklam yağmuruna tutulurken, hakikati s&amp;ouml;ylemeye &amp;ccedil;alışan kanallara bu yağmurdan tek damla d&amp;uuml;şm&amp;uuml;yor.&amp;rdquo; dedi.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi Genel Başkan Yardımcısı Yılmaz, &amp;ldquo;Siz bakmayın Ekran &amp;uuml;nl&amp;uuml;s&amp;uuml; s&amp;ouml;zde gazetecilerin sa&amp;ccedil;ından tırnağından kokain fışkırmasına ger&amp;ccedil;ek gazeteciler, y&amp;uuml;zlerce medya emek&amp;ccedil;isi proteine ulaşmakta zorlanıyor. &amp;Ccedil;&amp;uuml;nk&amp;uuml; kamu kaynakları ehliyete, liyakate reytinge g&amp;ouml;re değil, maalesef iktidara olan sadakate g&amp;ouml;re &amp;ouml;d&amp;uuml;llendiriliyor.&amp;rdquo; şeklinde konuştu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;Medya Sekt&amp;ouml;r&amp;uuml; Derin Bir Ekonomik Adaletsizliğin Pen&amp;ccedil;esindedir&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Bug&amp;uuml;n 10 Ocak &amp;Ccedil;alışan Gazeteciler g&amp;uuml;n&amp;uuml;, b&amp;uuml;t&amp;uuml;n basın emek&amp;ccedil;ilerinin kalemini haktan ve hakikatten yana kullanan b&amp;uuml;t&amp;uuml;n gazetecilerin &amp;ccedil;alışan gazeteciler g&amp;uuml;n&amp;uuml;n&amp;uuml; kutluyoruz.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;10 Ocak&amp;rsquo;ta &amp;uuml;lkemizdeki acı bir ger&amp;ccedil;eği de ifade etmek zorundayız. Maalesef bug&amp;uuml;n kutlama yapmak i&amp;ccedil;in değil bir mesleğin can &amp;ccedil;ekişini, uğradığı haksızlıkları, maruz bırakıldığı kuşatmayı haykırmak i&amp;ccedil;in buradayız. Medya sekt&amp;ouml;r&amp;uuml; bug&amp;uuml;n derin bir ekonomik adaletsizliğin pen&amp;ccedil;esindedir. Tıpkı emeklilerimizde, tıpkı asgari &amp;uuml;cretle evine helal lokma taşımaya &amp;ccedil;alışan milyonlarca asgari &amp;uuml;cretlimizde olduğu gibi, medya sekt&amp;ouml;r&amp;uuml;n&amp;uuml;n ger&amp;ccedil;ek emek&amp;ccedil;ileri ger&amp;ccedil;ek gazetecilerde tarihinin en zor en sıkıntılı d&amp;ouml;nemlerinden birini yaşıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Siz bakmayın Ekran &amp;uuml;nl&amp;uuml;s&amp;uuml; s&amp;ouml;zde gazetecilerin sa&amp;ccedil;ından tırnağından kokain fışkırmasına. Ger&amp;ccedil;ek gazeteciler, y&amp;uuml;zlerce medya emek&amp;ccedil;isi proteine ulaşmakta zorlanıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:start&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml; kamu kaynakları ehliyete, liyakate reytinge g&amp;ouml;re değil, maalesef iktidara olan sadakate g&amp;ouml;re &amp;ouml;d&amp;uuml;llendiriliyor.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

